from vpython import *
x = sphere(color = color.magenta, make_trail = True)
y = sphere(color = color.cyan)
while True :
    rate(100)
    k = keysdown()
    if 'left' in k : 
        x.pos.x = x.pos.x - 0.1
    if 'right' in k : 
        x.pos.x = x.pos.x + 0.1
    if 'up' in k : 
        x.pos.y += 0.1
    if 'down' in k : 
        x.pos.y -= 0.1
    if mag(x.pos - y.pos) <= 2 : 
        y.color = color.red
        y.opacity = 0.5
    else : 
        y.color = color.cyan
        y.opacity = 1
    if 'q' in k : 
        break
